			// 생년월일 0000-00-00 변경
			function dateForm(brdt){
			    var dt = "";
			    if(brdt.length == 8){
			        dt = brdt.substr(0, 4) + "-" + brdt.substr(4, 2) + "-" + brdt.substr(6, 2);    
			    } else {
			        dt = brdt;
			    }
			    return dt;
			}

			// 전화번호 000-0000-0000 변경
			function tellForm(tellNo){
			    var telNo = "";
			    if(tellNo.length == 11){
			        telNo = tellNo.substr(0, 3) + "-" + tellNo.substr(3, 4) + "-" + tellNo.substr(7, 4);
			    } else if(tellNo.length == 10){
			        if(tellNo.substr(0, 2) == "02"){
			            telNo = tellNo.substr(0, 2) + "-" + tellNo.substr(2, 4) + "-" + tellNo.substr(6, 4);    
			        } else {
			            telNo = tellNo.substr(0, 3) + "-" + tellNo.substr(3, 3) + "-" + tellNo.substr(6, 4);
			        }
			        
			    } else {
			        telNo = tellNo;
			    }
			    return telNo;
			}
